  ('22a00000-0000-4000-8000-000000000001'::uuid, $legacynews${"title":"La nuit tombe : l’Équipier sans tête entre en chasse","category":"Événement Halloween","summary":"Bientôt, Cycling Hollow ouvrira sa route. Échappez au lugubre poursuivant, récoltez des roues démoniaques et remportez une ribambelle de gains, des surprises aux récompenses les plus rares.","body":"Bientôt, Cycling Hollow ouvrira sa route. Échappez au lugubre poursuivant, récoltez des roues démoniaques et remportez une ribambelle de gains, des surprises aux récompenses les plus rares.","title_en":"Night falls: the Headless Domestique joins the chase","category_en":"Halloween event","summary_en":"Coming soon, Cycling Hollow will open its road. Escape the grim pursuer, collect demonic wheels and claim a host of prizes, from eerie surprises to the rarest rewards.","body_en":"Coming soon, Cycling Hollow will open its road. Escape the grim pursuer, collect demonic wheels and claim a host of prizes, from eerie surprises to the rarest rewards.","image_path":"/images/announcements/halloween-2026-gameplay.png","image_alt":"L’événement Halloween de Cyclo Stratège avec l’Équipier sans tête lancé à la poursuite d’un cycliste","link_url":"/inscription","link_label":"Rejoindre le peloton avant la nuit"}$legacynews$::jsonb, now()),
  ('22a00000-0000-4000-8000-000000000002'::uuid, $legacynews${"title":"La Saison 3 donne le pouvoir aux fédérations","category":"Saison 3","summary":"La nouvelle saison est lancée. Les Directeurs Sportifs rejoignent leur fédération nationale pour élire leur président, gérer une trésorerie commune, développer des infrastructures et composer les sélections qui défendront leur pays.","body":"La nouvelle saison est lancée. Les Directeurs Sportifs rejoignent leur fédération nationale pour élire leur président, gérer une trésorerie commune, développer des infrastructures et composer les sélections qui défendront leur pays.","title_en":"Season 3 puts federations in charge","category_en":"Season 3","summary_en":"The new season is live. Sports Directors join their national federation to elect a president, manage shared finances, develop infrastructure and shape the selections that will represent their country.","body_en":"The new season is live. Sports Directors join their national federation to elect a president, manage shared finances, develop infrastructure and shape the selections that will represent their country.","image_path":"/images/announcements/saison-3-federations.webp","image_alt":"Un peloton rejoint un siège fédéral au lever du jour dans un paysage de montagne","link_url":"/jeu/federation","link_label":"Prendre place dans ma fédération"}$legacynews$::jsonb, timestamp '2026-09-11 12:00:00' at time zone 'Europe/Paris'),
  ('22a00000-0000-4000-8000-000000000003'::uuid, $legacynews${"title":"Le parrainage passe à la vitesse supérieure","category":"Communauté","summary":"Invitez de nouveaux Directeurs Sportifs et débloquez des objets rares, des primes pouvant atteindre 2 000 000 €, ainsi que la tenue du Parrain et le fedora exclusif du Don.","body":"Invitez de nouveaux Directeurs Sportifs et débloquez des objets rares, des primes pouvant atteindre 2 000 000 €, ainsi que la tenue du Parrain et le fedora exclusif du Don.","title_en":"Referral rewards shift up a gear","category_en":"Community","summary_en":"Invite new Sports Directors and unlock rare items, career bonuses worth up to €2,000,000, the Godfather outfit and the Don’s exclusive fedora.","body_en":"Invite new Sports Directors and unlock rare items, career bonuses worth up to €2,000,000, the Godfather outfit and the Don’s exclusive fedora.","image_path":"/images/game-workspace-escape.webp","image_alt":"Un peloton gravit une route de montagne au lever du jour","link_url":"/jeu/parrainage","link_label":"Découvrir les nouveaux gains"}$legacynews$::jsonb, timestamp '2026-08-28 12:00:00' at time zone 'Europe/Paris'),
  ('22a00000-0000-4000-8000-000000000004'::uuid, $legacynews${"title":"Le Patch 4 développe vos infrastructures","category":"Mise à jour","summary":"Le centre d’entraînement s’étoffe et sept installations spécialisées ouvrent de nouvelles possibilités pour préparer, récupérer, rechercher et faire rayonner votre équipe.","body":"Le centre d’entraînement s’étoffe et sept installations spécialisées ouvrent de nouvelles possibilités pour préparer, récupérer, rechercher et faire rayonner votre équipe.","title_en":"Patch 4 expands your infrastructure","category_en":"Update","summary_en":"The training centre grows with seven specialist facilities for preparation, recovery, research and team development.","body_en":"The training centre grows with seven specialist facilities for preparation, recovery, research and team development.","image_path":"/images/infrastructure/training-center.webp","image_alt":"Le centre d’entraînement de l’équipe","link_url":"/nouveautes#patch-4","link_label":"Voir le détail du Patch 4"}$legacynews$::jsonb, timestamp '2026-08-12 12:00:00' at time zone 'Europe/Paris'),
  ('22a00000-0000-4000-8000-000000000005'::uuid, $legacynews${"title":"Le Patch 3 est déployé","category":"Mise à jour","summary":"Cette troisième livraison enrichit la course et le quotidien du directeur sportif : Cyclogazette, interviews d’après-course, minijeux juniors revus, gestion du matériel, plans d’entraînement groupés et de nombreuses améliorations d’interface, de performance et d’équilibrage.","body":"Cette troisième livraison enrichit la course et le quotidien du directeur sportif : Cyclogazette, interviews d’après-course, minijeux juniors revus, gestion du matériel, plans d’entraînement groupés et de nombreuses améliorations d’interface, de performance et d’équilibrage.","title_en":"Patch 3 is live","category_en":"Update","summary_en":"Cyclogazette, post-race interviews, revised junior minigames, equipment management, group training plans and many interface, performance and balance improvements.","body_en":"Cyclogazette, post-race interviews, revised junior minigames, equipment management, group training plans and many interface, performance and balance improvements.","image_path":"","image_alt":"","link_url":"https://discord.com/channels/1530228791857909891/1530867588093968544","link_label":"Voir le détail du Patch 3"}$legacynews$::jsonb, timestamp '2026-08-01 12:00:00' at time zone 'Europe/Paris'),
  ('22a00000-0000-4000-8000-000000000006'::uuid, $legacynews${"title":"Le Patch 2 est déployé","category":"Mise à jour","summary":"De nouvelles fonctionnalités, des interfaces affinées, des équilibrages de gameplay et de nombreux correctifs sont arrivés en production.","body":"De nouvelles fonctionnalités, des interfaces affinées, des équilibrages de gameplay et de nombreux correctifs sont arrivés en production.","title_en":"Patch 2 is live","category_en":"Update","summary_en":"New features, refined interfaces, gameplay balancing and numerous fixes have reached production.","body_en":"New features, refined interfaces, gameplay balancing and numerous fixes have reached production.","image_path":"","image_alt":"","link_url":"https://discord.com/channels/1530228791857909891/1530867588093968544","link_label":"Voir le détail du Patch 2"}$legacynews$::jsonb, timestamp '2026-07-28 12:00:00' at time zone 'Europe/Paris'),
  ('22a00000-0000-4000-8000-000000000007'::uuid, $legacynews${"title":"Le Patch 1 pose les premières fondations","category":"Mise à jour","summary":"Parcours de jeu consolidés, courses et matériel enrichis, progression affinée et identité visuelle des coureurs harmonisée.","body":"Parcours de jeu consolidés, courses et matériel enrichis, progression affinée et identité visuelle des coureurs harmonisée.","title_en":"Patch 1 lays the first foundations","category_en":"Update","summary_en":"Consolidated game flows, richer racing and equipment, refined progression and consistent rider visuals.","body_en":"Consolidated game flows, richer racing and equipment, refined progression and consistent rider visuals.","image_path":"","image_alt":"","link_url":"https://discord.com/channels/1530228791857909891/1530867588093968544","link_label":"Voir le détail du Patch 1"}$legacynews$::jsonb, timestamp '2026-07-26 12:00:00' at time zone 'Europe/Paris'),
  ('22a00000-0000-4000-8000-000000000008'::uuid, $legacynews${"title":"MVP déployé, pré-alpha lancée","category":"Développement","summary":"La première version de Cyclo Stratège est en ligne. La phase pré-alpha commence et le jeu va désormais évoluer au fil des tests et de vos retours.","body":"La première version de Cyclo Stratège est en ligne. La phase pré-alpha commence et le jeu va désormais évoluer au fil des tests et de vos retours.","title_en":"MVP deployed, pre-alpha launched","category_en":"Development","summary_en":"The first Cyclo Stratège version is online. The pre-alpha begins and the game will evolve through testing and player feedback.","body_en":"The first Cyclo Stratège version is online. The pre-alpha begins and the game will evolve through testing and player feedback.","image_path":"","image_alt":"","link_url":"","link_label":""}$legacynews$::jsonb, timestamp '2026-07-26 12:00:00' at time zone 'Europe/Paris'),
  ('22a00000-0000-4000-8000-000000000009'::uuid, $legacynews${"title":"Le Discord ouvre ses portes","category":"Communauté","summary":"Un espace pour signaler les bugs, partager vos idées et échanger avec nous autour de l’application.","body":"Un espace pour signaler les bugs, partager vos idées et échanger avec nous autour de l’application.","title_en":"Discord opens its doors","category_en":"Community","summary_en":"A place to report bugs, share ideas and talk with us about the game.","body_en":"A place to report bugs, share ideas and talk with us about the game.","image_path":"","image_alt":"","link_url":"https://discord.gg/EbupEFEQC8","link_label":"Rejoindre le Discord"}$legacynews$::jsonb, timestamp '2026-07-26 12:00:00' at time zone 'Europe/Paris')
), normalized as (
